export class HierarchicalOrchestrator {
  constructor() {
    this.layers = [];
  }

  addLayer(layer) {
    if (typeof layer !== 'function') {
      throw new Error('Layer must be a function.');
    }
    this.layers.push(layer);
  }

  execute(input) {
    let result = input;
    for (const layer of this.layers) {
      result = layer(result);
      if (result.escalate) {
        console.log('Escalation triggered at layer:', layer.name);
        return result;
      }
    }
    return result;
  }
}